"""Canonical claim identity and digest of the generated bytes present."""

from __future__ import annotations

import copy
import hashlib
import json
import os
from collections.abc import Mapping

from . import core
from . import recipe as recipe_module


def _canonical(value: object) -> bytes:
    """Use the identity format's default JSON separators and ASCII escaping."""
    try:
        return json.dumps(value, sort_keys=True).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise core.ClaimError(f"cannot serialize claim identity: {exc}") from exc


def _claim_format(recipe: Mapping) -> int:
    """Return the declared format, treating an omitted version as format 1."""
    return recipe["claim"].get("format", 1)


def _preimage_recipe(recipe: Mapping) -> dict:
    """Remove non-identity guidance and, in format 4, canonicalize step order."""
    result = copy.deepcopy(dict(recipe))
    version = _claim_format(recipe)
    if version >= 3:
        for step in result.get("step", []):
            for key in core.GUIDANCE_KEYS:
                step.pop(key, None)
    if version >= 4 and "step" in result:
        result["step"].sort(key=_canonical)
    return result


def _parts(recipe: Mapping, directory: os.PathLike[str] | str) -> dict[str, str]:
    """Collect the nested recipe serialization and all pinned file digests."""
    parts = {
        "digest": core.DIGEST,
        "recipe": _canonical(_preimage_recipe(recipe)).decode("ascii"),
    }
    for name in recipe_module._inputs(recipe, directory):
        parts["input:" + name] = core._hash_file(core._safe(directory, name))
    for step in recipe_module._steps(recipe):
        kind = step.get("kind")
        step_class = step.get("class", "generated" if kind == "produce" else "pinned")
        if step_class not in ("generated", "free"):
            name = step["output"]
            parts["pinned:" + name] = core._hash_file(core._safe(directory, name))
    return parts


def root(recipe: Mapping, directory: os.PathLike[str] | str) -> str:
    """Name a claim by its recipe and pinned bytes."""
    return hashlib.sha256(_canonical(_parts(recipe, directory))).hexdigest()


def build_digest(directory: os.PathLike[str] | str) -> str:
    """Hash the generated outputs currently present, excluding imported ones."""
    parsed = recipe_module.load_recipe(directory)
    entries: list[list[str]] = []
    for step in recipe_module._steps(parsed):
        kind = step.get("kind")
        step_class = step.get("class", "generated" if kind == "produce" else "pinned")
        if step_class not in ("generated", "free") or "from" in step:
            continue
        name = step["output"]
        path = core._safe(directory, name)
        if os.path.lexists(path):
            entries.append([name, core._hash_file(path)])
    entries.sort(key=lambda entry: entry[0])
    return hashlib.sha256(_canonical(entries)).hexdigest()
